def publish(self, topic, payload):
    """Send a message.

    Returns:
        the message id
    """
    return self.bus.send(topic, payload)

def load(path):
    settings = {}
    for line in open(path):
        key, value = line.split(':')
        settings[key] = value
    return settings

def execute(self, config):
    """Run the subcommand with the given settings object."""
    self.run(config)
